// Test double of `expo/internal/unstable-autolinking-exports`, used by skill discovery.
// It resolves the direct dependencies listed in the project's package.json inside `node_modules`,
// which is all the e2e fixtures need. The real implementation scans transitively.
const fs = require('node:fs');
const path = require('node:path');

function readJson(filePath) {
  try {
    return JSON.parse(fs.readFileSync(filePath, 'utf8'));
  } catch {
    return null;
  }
}

function makeCachedDependenciesLinker({ projectRoot }) {
  let cache;

  async function scanDependenciesRecursively() {
    if (cache) {
      return cache;
    }

    const pkg = readJson(path.join(projectRoot, 'package.json')) ?? {};
    const names = Object.keys({ ...pkg.dependencies, ...pkg.devDependencies });

    const resolutions = {};
    for (const name of names) {
      const dependencyPath = path.join(projectRoot, 'node_modules', name);
      const dependencyPkg = readJson(path.join(dependencyPath, 'package.json'));
      // An unresolved dependency is reported as `undefined`, like the real linker does.
      resolutions[name] = dependencyPkg
        ? {
            name: dependencyPkg.name ?? name,
            version: dependencyPkg.version ?? '0.0.0',
            path: dependencyPath,
            originPath: dependencyPath,
            depth: 0,
            source: 'searchPath',
          }
        : undefined;
    }

    cache = resolutions;
    return resolutions;
  }

  return {
    scanDependenciesRecursively,
    getOptionsForPlatform: () => ({}),
  };
}

module.exports = { makeCachedDependenciesLinker };
